```javascript
// Alternative: returns undefined instead of null
function findFirstAlt(arr, predicate) {
  for (const item of arr) {
    if (predicate(item)) return item;
  }
  return undefined; // same as native Array.prototype.find
}

// Alternative: wrapped result to avoid ambiguity
